function makeLine(x1, z1, x2, z2, w) {
  const lw = w || LINE_W;
  const dx = x2 - x1, dz = z2 - z1;
  const len = Math.hypot(dx, dz);
  const g = new THREE.BoxGeometry(len, 0.022, lw);
  const m = new THREE.Mesh(g, lineMat);
  m.position.set((x1 + x2) / 2, 0.030, (z1 + z2) / 2);
  m.rotation.y = -Math.atan2(dz, dx);
  return m;
}
