function makeNetTexture() {
  const c = document.createElement('canvas'); c.width = 1024; c.height = 256;
  const g = c.getContext('2d'); g.clearRect(0, 0, c.width, c.height);
  // Red oscura sin bandas blancas laterales
  g.strokeStyle = 'rgba(15, 15, 15, 0.80)'; g.lineWidth = 1.3;
  for (let x = 0; x <= c.width; x += 11) { g.beginPath(); g.moveTo(x, 0); g.lineTo(x, c.height); g.stroke(); }
  for (let y = 0; y <= c.height; y += 11) { g.beginPath(); g.moveTo(0, y); g.lineTo(c.width, y); g.stroke(); }
  // Banda superior blanca (tape) - solo arriba, más delgada y limpia
  g.fillStyle = 'rgba(255,255,255,0.92)'; g.fillRect(0, 0, c.width, 14);
  // Sin banda inferior — eliminada para no generar línea en el suelo
  return new THREE.CanvasTexture(c);
}
